    /// <summary>
    /// Finds or create an excise register entry based on the buffer METExciseRegisterEntry.
    /// </summary>
    /// <param name="_exciseRegisterEntry">The METExciseRegisterEntry buffer to find or create.</param>
    /// <returns>
    /// The found or newly created METExciseRegisterEntry.
    /// </returns>
    public static METExciseRegisterEntry findOrCreate(METExciseRegisterEntry _exciseRegisterEntry)
    {
        METExciseRegisterEntry ret = METExciseRegisterEntry::find(_exciseRegisterEntry.Lodgement, _exciseRegisterEntry.SiteId, _exciseRegisterEntry.ItemId, _exciseRegisterEntry.OrderNumber);

        if (!ret)
        {
            ret.data(_exciseRegisterEntry);
            ret.ReferenceId = guid2Str(newGuid());
            ret.VersionNumberRegister = 1;
            ret.ValidFrom = DateTimeUtil::utcNow();
            ret.ValidTo = DateTimeUtil::maxValue();
            ret.insert();
        }

        return ret;
    }

public static METExciseRegisterEntry findReferenceId(METExciseRegisterReferenceId       _referenceId,
                                                    boolean                             _forUpdate = false,
                                                    utcdatetime                         _validFrom = DateTimeUtil::utcNow(),
                                                    utcdatetime                         _validTo = DateTimeUtil::maxValue())
{
    METExciseRegisterEntry   exciseRegisterEntry = null;
    exciseRegisterEntry.selectForUpdate(_forUpdate);
    if (_referenceId)
    {
        select firstonly validtimestate(_validFrom, _validTo) exciseRegisterEntry
            where exciseRegisterEntry.ReferenceId == _referenceId;
    }
    return exciseRegisterEntry;
}

    /// </summary>
    /// <param name="_recId">The RecId of the excise register entry.</param>
    /// <param name="_forUpdate">If true, locks the record for update.</param>
    /// <returns>The found METExciseRegisterEntry or null if not found.</returns> 
    public static METExciseRegisterEntry findRecId(RefRecId         _recId, 
                                                   boolean          _forUpdate = false,
                                                   utcdatetime     _validFrom = DateTimeUtil::minValue(),
                                                   utcdatetime     _validTo = DateTimeUtil::maxValue())
    {
        METExciseRegisterEntry   exciseRegisterEntry = null;

        exciseRegisterEntry.selectForUpdate(_forUpdate);

        if (_recId)
        {
            select firstonly validtimestate(_validFrom, _validTo) exciseRegisterEntry
                where exciseRegisterEntry.RecId == _recId;
        }

        return exciseRegisterEntry;
    }

